/* Generated byte vectors, never user media. */
#include <assert.h>
#include <stdio.h>
#include "MP42StrictHEVC.h"
int main(void) {
    uint8_t c[44] = {1}; c[21] = 3; c[22] = 3;
    size_t p = 23;
    for (unsigned t = 32; t <= 34; t++) {
        c[p++] = 0x80 | t; c[p++] = 0; c[p++] = 1;
        c[p++] = 0; c[p++] = 2; c[p++] = t << 1; c[p++] = 1;
    }
    assert(p == sizeof(c)); assert(MP42HEVCConfig(c, sizeof(c)));
    uint8_t original[] = {0,0,0,2,64,1, 0,0,0,2,66,1, 0,0,0,2,68,1,
                          0,0,0,3,78,1,99, 0,0,0,3,124,1,55, 0,0,0,3,2,1,42};
    uint8_t expected[] = {0,0,0,3,78,1,99, 0,0,0,3,124,1,55, 0,0,0,3,2,1,42};
    uint8_t sample[sizeof(original)]; memcpy(sample, original, sizeof(sample));
    uint32_t len = sizeof(sample);
    assert(MP42HEVCNormalize(c, sizeof(c), sample, &len));
    assert(len == sizeof(expected) && !memcmp(sample, expected, len));
    assert(MP42HEVCNormalize(c, sizeof(c), sample, &len)); // idempotent
    // Every truncation is bounded; a malformed config cannot edit the sample.
    for (size_t n = 0; n < sizeof(c); n++) {
        memcpy(sample, original, sizeof(sample)); len = sizeof(sample);
        assert(!MP42HEVCNormalize(c, n, sample, &len));
        assert(len == sizeof(sample) && !memcmp(sample, original, len));
    }
    // Changed VPS, invalid length, forbidden bit, nonzero layer, temporal id zero.
    unsigned offsets[] = {5,3,4,5,5}; unsigned values[] = {2,255,192,9,0};
    for (unsigned k = 0; k < 5; k++) {
        memcpy(sample, original, sizeof(sample)); sample[offsets[k]] = values[k];
        uint8_t snapshot[sizeof(sample)]; memcpy(snapshot, sample, sizeof(sample)); len = sizeof(sample);
        assert(!MP42HEVCNormalize(c, sizeof(c), sample, &len));
        assert(!memcmp(sample, snapshot, sizeof(sample)) && len == sizeof(sample));
    }
    memcpy(sample, original, sizeof(sample)); len = 18;
    assert(!MP42HEVCNormalize(c, sizeof(c), sample, &len)); // no retained sample
    c[22] = 2; assert(!MP42HEVCConfig(c, sizeof(c))); // missing PPS / trailing data
    puts("strict HEVC vectors passed (retained SEI/RPU/VCL, idempotence, malformed and changing parameters)");
}
